//! Typed view of `spec/spec.toml`, its validation rules, and the two code
//! generators (SystemVerilog package and Rust consts).
//!
//! Everything here is deterministic: maps are `BTreeMap`, emitted order is
//! either canonical (fixed name lists) or sorted by value, and no timestamps.

use serde::Deserialize;
use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// Header line on every generated file.
pub const GENERATED_HEADER: &str = "GENERATED by splitsys-spec — DO NOT EDIT";

/// Canonical latency names, in emission order.
pub const LATENCY_NAMES: [&str; 7] = ["L_PE", "L_RD", "L_SETUP", "L_RQ", "L_WB", "L_ACCEPT", "L_DONE"];
/// Canonical mode names, in encoding order.
pub const MODE_NAMES: [&str; 3] = ["FULL", "STRIP", "INDEP"];
/// Canonical buffer names, in region-id order.
pub const BUFFER_NAMES: [&str; 4] = ["WBUF", "ABUF", "OBUF", "RQPARAM"];
/// Canonical descriptor field names, in byte order.
pub const DESC_FIELD_NAMES: [&str; 10] =
    ["mode", "flags", "m", "k", "n", "a_base", "w_base", "out_base", "rq_base", "reserved"];
/// Required opcode names.
pub const OPCODE_NAMES: [&str; 8] =
    ["PING", "WRITE_MEM", "READ_MEM", "RUN_GEMM", "POLL", "READ_COUNTERS", "SELFTEST", "SET_DISPLAY"];
/// Required status names.
pub const STATUS_NAMES: [&str; 5] = ["ACK", "NACK_CRC", "NACK_OPCODE", "NACK_RANGE", "BUSY"];
/// Required poll-state names.
pub const POLL_NAMES: [&str; 4] = ["IDLE", "BUSY", "DONE", "ERROR"];

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Spec {
    pub meta: Meta,
    pub array: Array,
    pub modes: BTreeMap<String, i64>,
    pub latency: BTreeMap<String, Latency>,
    pub drain: Drain,
    pub bench: Bench,
    pub buffers: BTreeMap<String, Buffer>,
    pub descriptor: Descriptor,
    pub requant: Requant,
    pub uart: Uart,
    pub protocol: Protocol,
    pub opcodes: BTreeMap<String, i64>,
    pub status: BTreeMap<String, i64>,
    pub poll: BTreeMap<String, i64>,
    pub counters: Counters,
    pub selftest: Selftest,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Meta {
    pub spec_version: String,
    pub proto_version: i64,
}

