#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Selftest {
    pub fletcher32_check_abcde: i64,
    pub fletcher32_check_abcdef: i64,
    pub fletcher32_check_abcdefgh: i64,
}

impl Selftest {
    /// (ASCII input, expected Fletcher-32) reference pairs, in emission order.
    pub fn checks(&self) -> [(&'static str, i64); 3] {
        [
            ("abcde", self.fletcher32_check_abcde),
            ("abcdef", self.fletcher32_check_abcdef),
            ("abcdefgh", self.fletcher32_check_abcdefgh),
        ]
    }
}

/// Errors from loading or validating the spec. Validation collects every
/// problem it finds, not just the first.
#[derive(Debug)]
pub enum SpecError {
    Io(PathBuf, std::io::Error),
    Parse(String),
    Invalid(Vec<String>),
}

impl std::fmt::Display for SpecError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SpecError::Io(p, e) => write!(f, "cannot read {}: {e}", p.display()),
            SpecError::Parse(e) => write!(f, "spec.toml parse error: {e}"),
            SpecError::Invalid(v) => {
                writeln!(f, "spec.toml is inconsistent ({} problem(s)):", v.len())?;
                for e in v {
                    writeln!(f, "  - {e}")?;
                }
                Ok(())
            }
        }
    }
}

impl std::error::Error for SpecError {}

/// Path of `spec/spec.toml` relative to this crate (works for `cargo run`/`cargo test`).
pub fn default_spec_path() -> PathBuf {
    repo_root().join("spec").join("spec.toml")
}

/// Repository root, derived from this crate's manifest directory (`sw/crates/spec`).
pub fn repo_root() -> PathBuf {
    let crate_dir = Path::new(env!("CARGO_MANIFEST_DIR"));
    crate_dir.ancestors().nth(3).map_or_else(|| crate_dir.join("../../.."), Path::to_path_buf)
}

/// Generated SystemVerilog package path.
pub fn sv_out_path() -> PathBuf {
    repo_root().join("rtl").join("gen").join("splitsys_pkg.sv")
}

/// Generated Rust consts path.
pub fn rs_out_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("src").join("generated.rs")
}

/// Reference CRC-8 (MSB-first, no reflection, no final xor), used to check
/// `crc8_check`. Host and RTL implement their own; this pins the definition.
pub fn crc8(poly: u8, init: u8, data: &[u8]) -> u8 {
    let mut crc = init;
    for &b in data {
        crc ^= b;
        for _ in 0..8 {
            crc = if crc & 0x80 != 0 { (crc << 1) ^ poly } else { crc << 1 };
        }
    }
    crc
}

/// Reference Fletcher-32 exactly as SPEC §3.9 defines it: 16-bit
/// little-endian words (byte 2i is the low byte), an odd trailing byte is
/// zero-padded, both sums start at 0 and are kept in 0..=65534 (mod 65535),
/// result = (sum2 << 16) | sum1.
pub fn fletcher32(data: &[u8]) -> u32 {
    let (mut s1, mut s2) = (0u32, 0u32);
    for chunk in data.chunks(2) {
        let lo = u32::from(chunk[0]);
        let hi = u32::from(*chunk.get(1).unwrap_or(&0));
        s1 = (s1 + (lo | (hi << 8))) % 65535;
        s2 = (s2 + s1) % 65535;
    }
    (s2 << 16) | s1
}

fn ceil_div(a: i64, b: i64) -> i64 {
    (a + b - 1) / b
}

fn clog2(x: i64) -> i64 {
    let mut n = 0;
    while (1i64 << n) < x {
        n += 1;
    }
    n
}

fn is_ident(s: &str) -> bool {
    !s.is_empty()
        && s.chars().next().is_some_and(|c| c.is_ascii_lowercase())
        && s.chars().all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == '_')
}

impl Spec {
    /// Parse without validating.
    pub fn parse(text: &str) -> Result<Spec, SpecError> {
        toml::from_str(text).map_err(|e| SpecError::Parse(e.to_string()))
    }

    /// Parse and validate.
    pub fn from_toml_str(text: &str) -> Result<Spec, SpecError> {
        let s = Spec::parse(text)?;
        s.validate()?;
        Ok(s)
    }

    /// Load and validate a spec file.
    pub fn load(path: &Path) -> Result<Spec, SpecError> {
        let text = std::fs::read_to_string(path).map_err(|e| SpecError::Io(path.to_path_buf(), e))?;
        Spec::from_toml_str(&text)
    }

    /// Load and validate `spec/spec.toml` from the repository.
    pub fn load_default() -> Result<Spec, SpecError> {
        Spec::load(&default_spec_path())
    }

    // ---- derived values (only meaningful after validate()) ----

    pub fn lat(&self, name: &str) -> &Latency {
        &self.latency[name]
    }
    pub fn buf(&self, name: &str) -> &Buffer {
        &self.buffers[name]
    }
    pub fn n_quads(&self) -> i64 {
        (self.array.rows / self.array.quad) * (self.array.cols / self.array.quad)
    }
    pub fn strip_tile_m(&self) -> i64 {
        self.array.rows / 2
    }
    pub fn strip_tile_n(&self) -> i64 {
        self.array.cols * 2
    }
    pub fn w_lanes(&self) -> i64 {
        self.array.cols * 2
    }
    /// Per-lane extra skew base for W lanes in STRIP mode (lanes >= COLS enter at row ROWS/2).
    pub fn w_skew_base_strip(&self) -> Vec<i64> {
        (0..self.w_lanes()).map(|j| if j < self.array.cols { 0 } else { self.array.rows / 2 }).collect()
    }
    /// STREAM start to operand word 0 at the array input port (L_RD + 1, SPEC §3.5).
    pub fn operand_port_offset(&self) -> i64 {
        self.lat("L_RD").value + 1
    }
    pub fn baud_div(&self) -> i64 {
        let u = &self.uart;
        let d = u.baud * u.oversample;
        (u.clk_hz + d / 2) / d
    }
    /// Baud error in parts per million (absolute).
    pub fn baud_error_ppm(&self) -> i64 {
        let u = &self.uart;
        let div = self.baud_div().max(1);
        let actual_x = u.clk_hz * 1_000_000 / (div * u.oversample); // baud * 1e6
        (actual_x - u.baud * 1_000_000).abs() / u.baud
    }
    pub fn desc_field(&self, name: &str) -> &DescField {
        self.descriptor.fields.iter().find(|f| f.name == name).expect("validated field")
    }
    fn sorted_by_value(m: &BTreeMap<String, i64>) -> Vec<(String, i64)> {
        let mut v: Vec<(String, i64)> = m.iter().map(|(k, v)| (k.clone(), *v)).collect();
        v.sort_by_key(|(k, v)| (*v, k.clone()));
        v
    }

    /// Check every consistency rule. Returns all problems at once.
    pub fn validate(&self) -> Result<(), SpecError> {
        let mut e: Vec<String> = Vec::new();
        let a = &self.array;

        // meta
        if !(0..=255).contains(&self.meta.proto_version) {
            e.push(format!("meta.proto_version {} must fit in u8", self.meta.proto_version));
        }
        if self.meta.spec_version.is_empty() || self.meta.spec_version.contains('"') {
            e.push("meta.spec_version must be a non-empty plain string".into());
        }

        // array
        let array_ok = a.rows > 0 && a.cols > 0 && a.quad > 0;
        if !array_ok {
            e.push(format!("array dims must be positive (rows={}, cols={}, quad={})", a.rows, a.cols, a.quad));
        } else {
            if a.cols % a.quad != 0 {
                e.push(format!("COLS % QUAD != 0 (cols={}, quad={})", a.cols, a.quad));
            }
            if a.rows % a.quad != 0 {
                e.push(format!("ROWS % QUAD != 0 (rows={}, quad={})", a.rows, a.quad));
            }
            if a.rows != 2 * a.quad || a.cols != 2 * a.quad {
                e.push(format!(
                    "array must be exactly 2x2 quadrants (rows = cols = 2*quad); got rows={}, cols={}, quad={}",
                    a.rows, a.cols, a.quad
                ));
            }
            if a.rows > 64 || a.cols > 64 {
                e.push("array dims > 64 are not supported by the counter popcount / lane widths".into());
            }
        }

        // modes
        check_enum(&mut e, "modes", &self.modes, &MODE_NAMES);
        for (i, n) in MODE_NAMES.iter().enumerate() {
            if self.modes.get(*n).is_some_and(|v| *v != i as i64) {
                e.push(format!("modes.{n} must be {i} (SPEC §3.2 encoding)"));
            }
        }

        // latencies
        for n in LATENCY_NAMES {
            match self.latency.get(n) {
                None => e.push(format!("latency.{n} is missing")),
                Some(l) => {
                    if l.value < 0 {
                        e.push(format!("latency.{n} = {} is negative", l.value));
                    }
                    if l.value > 1_000_000 {
                        e.push(format!("latency.{n} = {} is implausibly large", l.value));
                    }
                    if (n == "L_PE" || n == "L_RD") && l.value < 1 {
                        e.push(format!("latency.{n} must be >= 1 (registered pipeline)"));
                    }
                    if l.doc.trim().is_empty() {
                        e.push(format!("latency.{n}.doc must describe what is measured"));
                    }
                }
            }
        }
        for n in self.latency.keys() {
            if !LATENCY_NAMES.contains(&n.as_str()) {
                e.push(format!("latency.{n} is not a known latency (expected one of {LATENCY_NAMES:?})"));
            }
        }

        // drain
        if array_ok {
            if self.drain.t_drain_full != a.rows {
                e.push(format!("drain.t_drain_full {} must equal ROWS {}", self.drain.t_drain_full, a.rows));
            }
            if self.drain.t_drain_strip != a.rows / 2 {
                e.push(format!("drain.t_drain_strip {} must equal ROWS/2 {}", self.drain.t_drain_strip, a.rows / 2));
            }
        }

        // buffers
        let mut buffers_ok = true;
        for (i, n) in BUFFER_NAMES.iter().enumerate() {
            match self.buffers.get(*n) {
                None => {
                    buffers_ok = false;
                    e.push(format!("buffers.{n} is missing"));
                }
                Some(b) => {
                    if b.region != i as i64 {
                        e.push(format!("buffers.{n}.region must be {i} (SPEC §3.8 region ids)"));
                    }
                    if b.words <= 0 || (b.words & (b.words - 1)) != 0 {
                        buffers_ok = false;
                        e.push(format!("buffers.{n}.words = {} must be a positive power of two", b.words));
                    }
                    if b.word_bytes <= 0 {
                        buffers_ok = false;
                        e.push(format!("buffers.{n}.word_bytes must be positive"));
                    }
                }
            }
        }
        for n in self.buffers.keys() {
            if !BUFFER_NAMES.contains(&n.as_str()) {
                buffers_ok = false;
                e.push(format!("buffers.{n} is not a known buffer"));
            }
        }
        if buffers_ok && array_ok {
            let w = &self.buffers["WBUF"];
            let ab = &self.buffers["ABUF"];
            let o = &self.buffers["OBUF"];
            let rq = &self.buffers["RQPARAM"];
            if w.word_bytes != 2 * a.cols {
                e.push(format!(
                    "WBUF width must be 2*COLS lanes x 8 bits = {} bytes (16 lanes x int8); got {}",
                    2 * a.cols,
                    w.word_bytes
                ));
            }
            if ab.word_bytes != a.rows {
                e.push(format!("ABUF width must be ROWS lanes x 8 bits = {} bytes; got {}", a.rows, ab.word_bytes));
            }
            if o.word_bytes != 2 * a.cols {
                e.push(format!("OBUF width must be 2*COLS lanes x 8 bits = {} bytes; got {}", 2 * a.cols, o.word_bytes));
            }
            if rq.word_bytes != 4 {
                e.push(format!("RQPARAM word must be 4 bytes ({{8'h0, shift, mult}}); got {}", rq.word_bytes));
            }
            if o.word_bytes > 0 && (a.cols * 4) % o.word_bytes == 0 {
                let full = a.rows * (a.cols * 4 / o.word_bytes);
                let strip = (a.rows / 2) * (2 * a.cols * 4 / o.word_bytes);
                if self.drain.t_drain_full_int32 != full {
                    e.push(format!(
                        "drain.t_drain_full_int32 {} must equal ROWS * (COLS*4 B / OBUF word bytes) = {full}",
                        self.drain.t_drain_full_int32
                    ));
                }
                if self.drain.t_drain_strip_int32 != strip {
                    e.push(format!(
                        "drain.t_drain_strip_int32 {} must equal ROWS/2 * (2*COLS*4 B / OBUF word bytes) = {strip}",
                        self.drain.t_drain_strip_int32
                    ));
                }
            } else {
                e.push("OBUF word bytes must divide COLS*4 (whole int32 writes per FULL row)".into());
            }
            let d = &self.descriptor;
            if d.m_max > 0 && d.k_max > 0 && d.n_max > 0 {
                let a_need = ceil_div(d.m_max, a.rows) * d.k_max;
                if ab.words < a_need {
                    e.push(format!("ABUF words {} < ceil(M_MAX/ROWS)*K_MAX = {a_need}", ab.words));
                }
                let w_need = ceil_div(d.n_max, 2 * a.cols) * d.k_max;
                if w.words < w_need {
                    e.push(format!("WBUF words {} < ceil(N_MAX/16)*K_MAX = {w_need}", w.words));
                }
                let m_pad = ceil_div(d.m_max, a.rows) * a.rows;
                let o_need = ceil_div(d.n_max, 2 * a.cols) * m_pad;
                if o.words < o_need {
                    e.push(format!("OBUF words {} < ceil(N_MAX/16)*M_pad(M_MAX) = {o_need} (int8 path)", o.words));
                }
                if rq.words < d.n_max {
                    e.push(format!("RQPARAM entries {} < N_MAX {}", rq.words, d.n_max));
                }
            }
        }

        // descriptor
        let d = &self.descriptor;
        let names: Vec<&str> = d.fields.iter().map(|f| f.name.as_str()).collect();
        if names != DESC_FIELD_NAMES {
            e.push(format!("descriptor.fields must be exactly {DESC_FIELD_NAMES:?} in order; got {names:?}"));
        }
        let mut expect_off = 0;
        for f in &d.fields {
            if ![1, 2, 4].contains(&f.size) {
                e.push(format!("descriptor field {} size {} must be 1, 2 or 4", f.name, f.size));
            } else if f.offset % f.size != 0 {
                e.push(format!("descriptor field {} offset {} is not naturally aligned", f.name, f.offset));
            }
            if f.offset != expect_off {
                e.push(format!("descriptor field {} offset {} must be {expect_off} (contiguous)", f.name, f.offset));
            }
            expect_off = f.offset + f.size;
        }
        if expect_off != d.bytes {
            e.push(format!("descriptor fields cover {expect_off} bytes but descriptor.bytes = {}", d.bytes));
        }
        for (fname, size) in [("mode", 1), ("flags", 1)] {
            if let Some(f) = d.fields.iter().find(|f| f.name == fname) {
                if f.size != size {
                    e.push(format!("descriptor field {fname} must be {size} byte"));
                }
            }
        }
        for (n, v) in [("flag_requant_en", d.flag_requant_en), ("flag_out_int32", d.flag_out_int32)] {
            if !(1..=0x80).contains(&v) || (v & (v - 1)) != 0 {
                e.push(format!("descriptor.{n} = {v:#x} must be a single bit in a u8"));
            }
        }
        if d.flag_requant_en == d.flag_out_int32 {
            e.push("descriptor flag bits must differ".into());
        }
        let field_max = |name: &str| -> i64 {
            d.fields.iter().find(|f| f.name == name).map_or(0, |f| (1i64 << (8 * f.size.clamp(0, 4))) - 1)
        };
        for (n, lo, hi, field) in [("m", d.m_min, d.m_max, "m"), ("k", d.k_min, d.k_max, "k"), ("n", d.n_min, d.n_max, "n")] {
            if lo < 1 || lo > hi {
                e.push(format!("descriptor {n} range {lo}..{hi} must satisfy 1 <= min <= max"));
            }
            if hi > field_max(field) {
                e.push(format!("descriptor {n}_max {hi} does not fit its field"));
            }
        }
        // int32 accumulator never overflows: K_MAX * 128 * 128 < 2^31 (SPEC §1.2)
        if d.k_max * 128 * 128 >= (1i64 << 31) {
            e.push(format!("K_MAX {} lets the int32 accumulator overflow (K*128*128 >= 2^31)", d.k_max));
        }
        if buffers_ok && self.buffers["RQPARAM"].words > field_max("rq_base") + 1 {
            e.push("RQPARAM entries exceed the rq_base field range".into());
        }

        // requant
        let r = &self.requant;
        if !(1 <= r.mult_min && r.mult_min <= r.mult_max && r.mult_max <= 32767) {
            e.push(format!("requant mult range {}..{} must lie in 1..32767 (unsigned 15-bit)", r.mult_min, r.mult_max));
        }
        if !(1 <= r.shift_min && r.shift_min <= r.shift_max && r.shift_max <= 31) {
            e.push(format!("requant shift range {}..{} must lie in 1..31", r.shift_min, r.shift_max));
        }

        // uart
        let u = &self.uart;
        if u.clk_hz <= 0 || u.baud <= 0 || u.oversample <= 0 {
            e.push("uart clk_hz, baud, oversample must be positive".into());
        } else {
            if self.baud_div() < 1 {
                e.push(format!("uart: CLK_HZ/(BAUD*OVERSAMPLE) rounds to 0 (baud {} too high)", u.baud));
            } else if self.baud_error_ppm() > u.max_baud_error_permille * 1000 {
                e.push(format!(
                    "uart: integer divider {} gives baud error {} ppm > {} permille; pick another BAUD or a fractional divider",
                    self.baud_div(),
                    self.baud_error_ppm(),
                    u.max_baud_error_permille
                ));
            }
            let byte_time = 10 * u.clk_hz / u.baud;
            if u.rx_timeout < 2 * byte_time {
                e.push(format!("uart.rx_timeout {} must be >= 2 byte times ({} cycles)", u.rx_timeout, 2 * byte_time));
            }
            if u.rx_timeout >= (1i64 << 32) || u.clk_hz >= (1i64 << 32) {
                e.push("uart values must fit in 32 bits".into());
            }
        }

        // protocol
        let p = &self.protocol;
        for (n, v) in [
            ("sync_req", p.sync_req),
            ("sync_rsp", p.sync_rsp),
            ("crc8_poly", p.crc8_poly),
            ("crc8_init", p.crc8_init),
            ("crc8_check", p.crc8_check),
        ] {
            if !(0..=255).contains(&v) {
                e.push(format!("protocol.{n} = {v} must fit in u8"));
            }
        }
        if p.sync_req == p.sync_rsp {
            e.push("protocol sync_req and sync_rsp must differ".into());
        }
        if !(d.bytes..=65535).contains(&p.max_payload) {
            e.push(format!("protocol.max_payload {} must be in DESC_BYTES..=65535", p.max_payload));
        }
        if (0..=255).contains(&p.crc8_poly) && (0..=255).contains(&p.crc8_init) {
            let got = crc8(p.crc8_poly as u8, p.crc8_init as u8, b"123456789");
            if i64::from(got) != p.crc8_check {
                e.push(format!("protocol.crc8_check {:#04x} != computed CRC-8(\"123456789\") {got:#04x}", p.crc8_check));
            }
        }
        if p.ping_magic.len() != 4 || !p.ping_magic.bytes().all(|b| b.is_ascii_alphanumeric()) {
            e.push(format!("protocol.ping_magic {:?} must be 4 ASCII alphanumerics", p.ping_magic));
        }
        // READ_COUNTERS response must fit one frame
        if self.counters.bytes > 0 && (self.counters.order.len() as i64) * self.counters.bytes > p.max_payload {
            e.push("counters do not fit in one response payload".into());
        }

        // opcodes / status / poll
        check_enum(&mut e, "opcodes", &self.opcodes, &OPCODE_NAMES);
        check_enum(&mut e, "status", &self.status, &STATUS_NAMES);
        check_enum(&mut e, "poll", &self.poll, &POLL_NAMES);
        if self.status.get("ACK").is_some_and(|v| *v != 0) {
            e.push("status.ACK must be 0".into());
        }
        if self.opcodes.values().any(|v| *v == p.sync_req || *v == p.sync_rsp) {
            e.push("an opcode collides with a sync byte".into());
        }

        // counters
        let c = &self.counters;
        if !(1..=8).contains(&c.bytes) {
            e.push(format!("counters.bytes {} must be 1..=8", c.bytes));
        }
        if c.order.is_empty() {
            e.push("counters.order is empty".into());
        }
        let mut seen = std::collections::BTreeSet::new();
        for n in &c.order {
            if !is_ident(n) {
                e.push(format!("counter name {n:?} must be a lowercase identifier"));
            }
            if !seen.insert(n.clone()) {
                e.push(format!("counter {n} listed twice"));
            }
        }
        let mut required: Vec<String> = ["cycles_total", "cycles_setup", "cycles_stream", "cycles_flush", "cycles_drain", "cycles_stall", "mac_useful", "tiles"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        if array_ok && a.quad > 0 {
            for q in 0..self.n_quads() {
                required.push(format!("mac_useful_q{q}"));
            }
        }
        for r in &required {
            if !seen.contains(r) {
                e.push(format!("required counter {r} missing from counters.order"));
            }
        }

        // benchmarks (SPEC §1.1)
        let bn = &self.bench;
        let in_m = |m: i64| (d.m_min..=d.m_max).contains(&m);
        if bn.m_sweep.is_empty() || !bn.m_sweep.windows(2).all(|w| w[0] < w[1]) {
            e.push("bench.m_sweep must be non-empty and strictly increasing".into());
        }
        for &m in bn.m_sweep.iter().chain([bn.m_decode, bn.m_prefill].iter()) {
            if !in_m(m) {
                e.push(format!("bench M {m} outside M_MIN..M_MAX"));
            }
        }
        if bn.shapes.is_empty() {
            e.push("bench.shapes is empty".into());
        }
        let mut bnames = std::collections::BTreeSet::new();
        for s in &bn.shapes {
            if !is_ident(&s.name) || !bnames.insert(s.name.clone()) {
                e.push(format!("bench shape name {:?} must be a unique lowercase identifier", s.name));
            }
            if !(d.k_min..=d.k_max).contains(&s.k) || !(d.n_min..=d.n_max).contains(&s.n) {
                e.push(format!("bench shape {} (K={}, N={}) outside the descriptor ranges", s.name, s.k, s.n));
            }
        }

        // selftest reference values pin the Fletcher-32 definition
        let s = &self.selftest;
        for (input, want) in s.checks() {
            let got = fletcher32(input.as_bytes());
            if i64::from(got) != want {
                e.push(format!("selftest.fletcher32_check_{input} {want:#010x} != computed {got:#010x}"));
            }
        }

        if e.is_empty() {
            Ok(())
        } else {
            Err(SpecError::Invalid(e))
        }
    }

    // ------------------------------------------------------------------ Rust
    /// Render `sw/crates/spec/src/generated.rs`.
    pub fn render_rust(&self) -> String {
        let mut o = String::new();
        let a = &self.array;
        let d = &self.descriptor;
        let u = &self.uart;
        let p = &self.protocol;
        macro_rules! w {
            ($($t:tt)*) => { let _ = writeln!(o, $($t)*); };
        }
        w!("// {GENERATED_HEADER}");
        w!("// Source: spec/spec.toml (spec_version {}).", self.meta.spec_version);
        w!("// Regenerate: cd sw && cargo run -p splitsys-spec --bin gen");
        w!("// Prose and rationale: docs/SPEC.md, docs/DECISIONS.md.");
        w!("");
        w!("/// `meta.spec_version` of the spec this file was generated from.");
        w!("pub const SPEC_VERSION: &str = \"{}\";", self.meta.spec_version);
        w!("/// PING response version byte.");
        w!("pub const PROTO_VERSION: u8 = {};", self.meta.proto_version);
        w!("");
        w!("// ---- array (SPEC §3.2)");
        w!("pub const ROWS: usize = {};", a.rows);
        w!("pub const COLS: usize = {};", a.cols);
        w!("pub const QUAD: usize = {};", a.quad);
        w!("pub const N_QUADS: usize = {};", self.n_quads());
        w!("pub const N_PES: usize = {};", a.rows * a.cols);
        w!("pub const ENABLE_STRIP: bool = {};", a.enable_strip);
        for (n, v) in Self::sorted_by_value(&self.modes) {
            w!("pub const MODE_{n}: u8 = {v};");
        }
        w!("/// Output tile shape per mode (rows x cols of C).");
        w!("pub const FULL_TILE_M: usize = {};", a.rows);
        w!("pub const FULL_TILE_N: usize = {};", a.cols);
        w!("pub const STRIP_TILE_M: usize = {};", self.strip_tile_m());
        w!("pub const STRIP_TILE_N: usize = {};", self.strip_tile_n());
        w!("/// A operand lanes (ABUF word) and W operand lanes (WBUF word).");
        w!("pub const A_LANES: usize = {};", a.rows);
        w!("pub const W_LANES: usize = {};", self.w_lanes());
        w!("/// STRIP: W lanes >= STRIP_W_LANE_FIRST enter at row STRIP_W_ENTRY_ROW with extra skew STRIP_W_SKEW_BASE.");
        w!("pub const STRIP_W_LANE_FIRST: usize = {};", a.cols);
        w!("pub const STRIP_W_ENTRY_ROW: usize = {};", a.rows / 2);
        w!("pub const STRIP_W_SKEW_BASE: usize = {};", a.rows / 2);
        w!("/// Per-lane base delay of the W skew unit in STRIP mode (lane j total delay = base[j] + (j % COLS)).");
        w!("pub const W_SKEW_BASE_STRIP: [usize; {}] = {:?};", self.w_lanes(), self.w_skew_base_strip());
        w!("");
        w!("// ---- latencies in cycles (SPEC §4). *_PROVISIONAL = true until the RTL confirms the value.");
        for n in LATENCY_NAMES {
            let l = self.lat(n);
            w!("/// {}", l.doc);
            w!("pub const {n}: u64 = {};", l.value);
            w!("pub const {n}_PROVISIONAL: bool = {};", l.provisional);
        }
        w!("/// Cycles from STREAM start s to operand word k at the array input port: s + OPERAND_PORT_OFFSET + k.");
        w!("/// Derived: L_RD + 1 (one register between BRAM output and the array). SPEC §3.5.");
        w!("pub const OPERAND_PORT_OFFSET: u64 = {};", self.operand_port_offset());
        w!("");
        w!("/// One row of the latency table.");
        w!("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
        w!("pub struct LatencyInfo {{");
        w!("    pub name: &'static str,");
        w!("    pub value: u64,");
        w!("    pub provisional: bool,");
        w!("    pub doc: &'static str,");
        w!("}}");
        w!("");
        w!("pub const LATENCIES: [LatencyInfo; {}] = [", LATENCY_NAMES.len());
        for n in LATENCY_NAMES {
            let l = self.lat(n);
            w!("    LatencyInfo {{ name: \"{n}\", value: {}, provisional: {}, doc: {:?} }},", l.value, l.provisional, l.doc);
        }
        w!("];");
        w!("");
        w!("// ---- drain (SPEC §3.5, §4)");
        w!("pub const T_DRAIN_FULL: u64 = {};", self.drain.t_drain_full);
        w!("pub const T_DRAIN_STRIP: u64 = {};", self.drain.t_drain_strip);
        w!("/// int32 bypass DRAIN length per tile: 8 rows x 2 writes (FULL), 4 rows x 4 writes (STRIP). D-004.");
        w!("pub const T_DRAIN_FULL_INT32: u64 = {};", self.drain.t_drain_full_int32);
        w!("pub const T_DRAIN_STRIP_INT32: u64 = {};", self.drain.t_drain_strip_int32);
        let obw = self.buf("OBUF").word_bytes;
        w!("/// OBUF writes per drained row in int32 bypass.");
        w!("pub const INT32_WRITES_PER_ROW_FULL: u64 = {};", a.cols * 4 / obw);
        w!("pub const INT32_WRITES_PER_ROW_STRIP: u64 = {};", 2 * a.cols * 4 / obw);
        w!("/// int32 layout: OBUF words per output row of one 16-column block (SPEC §1.3).");
        w!("pub const INT32_WORDS_PER_ROW: usize = {};", 2 * a.cols * 4 / obw);
        w!("");
        w!("// ---- buffers (SPEC §3.4). Byte address = word_index * WORD_BYTES + lane.");
        w!("pub const N_REGIONS: usize = {};", BUFFER_NAMES.len());
        for n in BUFFER_NAMES {
            let b = self.buf(n);
            let pfx = if n == "RQPARAM" { "RQ" } else { n };
            w!("pub const REGION_{n}: u8 = {};", b.region);
            if n == "RQPARAM" {
                w!("pub const RQ_ENTRIES: usize = {};", b.words);
            } else {
                w!("pub const {pfx}_WORDS: usize = {};", b.words);
            }
            w!("pub const {pfx}_WORD_BYTES: usize = {};", b.word_bytes);
            w!("pub const {pfx}_BYTES: usize = {};", b.words * b.word_bytes);
            w!("pub const {pfx}_WORD_BITS: usize = {};", b.word_bytes * 8);
            w!("/// Word address bits (clog2 of the depth).");
            w!("pub const {pfx}_AW: u32 = {};", clog2(b.words));
        }
        w!("/// (name, region id, words, word bytes) in region-id order.");
        w!("pub const REGIONS: [(&str, u8, usize, usize); {}] = [", BUFFER_NAMES.len());
        for n in BUFFER_NAMES {
            let b = self.buf(n);
            w!("    (\"{n}\", {}, {}, {}),", b.region, b.words, b.word_bytes);
        }
        w!("];");
        w!("");
        w!("// ---- descriptor (SPEC §3.5), little-endian");
        w!("pub const DESC_BYTES: usize = {};", d.bytes);
        for f in &d.fields {
            w!("pub const DESC_OFF_{}: usize = {};", f.name.to_uppercase(), f.offset);
        }
        for f in &d.fields {
            w!("pub const DESC_SIZE_{}: usize = {};", f.name.to_uppercase(), f.size);
        }
        w!("pub const FLAG_REQUANT_EN: u8 = {:#04x};", d.flag_requant_en);
        w!("pub const FLAG_OUT_INT32: u8 = {:#04x};", d.flag_out_int32);
        w!("/// The only two legal `flags` values (SPEC §3.5 validation): int8 requant, int32 bypass.");
        w!("pub const FLAGS_INT8: u8 = {:#04x};", d.flag_requant_en);
        w!("pub const FLAGS_INT32: u8 = {:#04x};", d.flag_out_int32);
        w!("pub const M_MIN: usize = {};", d.m_min);
        w!("pub const M_MAX: usize = {};", d.m_max);
        w!("pub const K_MIN: usize = {};", d.k_min);
        w!("pub const K_MAX: usize = {};", d.k_max);
        w!("pub const N_MIN: usize = {};", d.n_min);
        w!("pub const N_MAX: usize = {};", d.n_max);
        w!("");
        w!("// ---- requant (SPEC §1.2)");
        w!("pub const RQ_MULT_MIN: u32 = {};", self.requant.mult_min);
        w!("pub const RQ_MULT_MAX: u32 = {};", self.requant.mult_max);
        w!("pub const RQ_SHIFT_MIN: u32 = {};", self.requant.shift_min);
        w!("pub const RQ_SHIFT_MAX: u32 = {};", self.requant.shift_max);
        w!("");
        w!("// ---- UART (SPEC §3.8)");
        w!("pub const CLK_HZ: u64 = {};", u.clk_hz);
        w!("pub const BAUD: u64 = {};", u.baud);
        w!("pub const OVERSAMPLE: u64 = {};", u.oversample);
        w!("/// round(CLK_HZ / (BAUD * OVERSAMPLE)): oversample tick divider.");
        w!("pub const BAUD_DIV: u64 = {};", self.baud_div());
        w!("/// Max core cycles between rx_valid strobes of consecutive bytes of one frame (SPEC §3.8).");
        w!("pub const RX_TIMEOUT: u64 = {};", u.rx_timeout);
        w!("");
        w!("// ---- protocol (SPEC §3.8)");
        w!("pub const SYNC_REQ: u8 = {:#04X};", p.sync_req);
        w!("pub const SYNC_RSP: u8 = {:#04X};", p.sync_rsp);
        w!("pub const MAX_PAYLOAD: usize = {};", p.max_payload);
        w!("pub const CRC8_POLY: u8 = {:#04x};", p.crc8_poly);
        w!("pub const CRC8_INIT: u8 = {:#04x};", p.crc8_init);
        w!("/// CRC-8 of ASCII \"123456789\" under CRC8_POLY/CRC8_INIT (MSB-first, no reflection, no xorout).");
        w!("pub const CRC8_CHECK: u8 = {:#04x};", p.crc8_check);
        let magic = p.ping_magic.as_bytes();
        let magic_le = u32::from_le_bytes([magic[0], magic[1], magic[2], magic[3]]);
        w!("/// PING magic as sent on the wire, as a little-endian u32 (wire byte i = bits 8i..8i+7).");
        w!("pub const PING_MAGIC_LE: u32 = 0x{magic_le:08X};");
        w!("/// Rust-only convenience: the same magic as wire bytes.");
        w!("pub const PING_MAGIC: [u8; 4] = *b\"{}\";", p.ping_magic);
        for (n, v) in Self::sorted_by_value(&self.opcodes) {
            w!("pub const OP_{n}: u8 = {v:#04x};");
        }
        w!("pub const OPCODES: [(&str, u8); {}] = [", self.opcodes.len());
        for (n, v) in Self::sorted_by_value(&self.opcodes) {
            w!("    (\"{n}\", {v:#04x}),");
        }
        w!("];");
        for (n, v) in Self::sorted_by_value(&self.status) {
            w!("pub const ST_{n}: u8 = {v};");
        }
        w!("pub const STATUSES: [(&str, u8); {}] = [", self.status.len());
        for (n, v) in Self::sorted_by_value(&self.status) {
            w!("    (\"{n}\", {v}),");
        }
        w!("];");
        for (n, v) in Self::sorted_by_value(&self.poll) {
            w!("pub const POLL_{n}: u8 = {v};");
        }
        w!("");
        w!("// ---- counters (SPEC §3.7), READ_COUNTERS order, each COUNTER_BYTES little-endian");
        w!("pub const N_COUNTERS: usize = {};", self.counters.order.len());
        w!("pub const COUNTER_BYTES: usize = {};", self.counters.bytes);
        w!("pub const COUNTER_BITS: u32 = {};", self.counters.bytes * 8);
        w!("pub const COUNTER_NAMES: [&str; N_COUNTERS] = [");
        for n in &self.counters.order {
            w!("    \"{n}\",");
        }
        w!("];");
        for (i, n) in self.counters.order.iter().enumerate() {
            w!("pub const CTR_{}: usize = {i};", n.to_uppercase());
        }
        w!("");
        w!("// ---- self-test reference values (SPEC §3.9 Fletcher-32 definition)");
        for (input, v) in self.selftest.checks() {
            w!("pub const FLETCHER32_CHECK_{}: u32 = {v:#010X};", input.to_uppercase());
        }
        w!("");
        w!("// ---- benchmark GEMMs (SPEC §1.1): one list for golden, cycle, and host");
        w!("/// A benchmark GEMM shape; M comes from BENCH_M_SWEEP / BENCH_M_DECODE / BENCH_M_PREFILL.");
        w!("#[derive(Debug, Clone, Copy, PartialEq, Eq)]");
        w!("pub struct BenchShape {{");
        w!("    pub name: &'static str,");
        w!("    pub k: usize,");
        w!("    pub n: usize,");
        w!("}}");
        w!("");
        let bn = &self.bench;
        w!("pub const BENCH_SHAPES: [BenchShape; {}] = [", bn.shapes.len());
        for s in &bn.shapes {
            w!("    BenchShape {{ name: \"{}\", k: {}, n: {} }},", s.name, s.k, s.n);
        }
        w!("];");
        w!("pub const BENCH_M_SWEEP: [usize; {}] = {:?};", bn.m_sweep.len(), bn.m_sweep);
        w!("pub const BENCH_M_DECODE: usize = {};", bn.m_decode);
        w!("pub const BENCH_M_PREFILL: usize = {};", bn.m_prefill);
        o
    }

    // ------------------------------------------------------------ SystemVerilog
    /// Render `rtl/gen/splitsys_pkg.sv`.
    pub fn render_sv(&self) -> String {
        let mut o = String::new();
        let a = &self.array;
        let d = &self.descriptor;
        let u = &self.uart;
        let p = &self.protocol;
        macro_rules! w {
            ($($t:tt)*) => { let _ = writeln!(o, $($t)*); };
        }
        let lp = |o: &mut String, name: &str, v: i64, comment: &str| {
            if comment.is_empty() {
                let _ = writeln!(o, "  localparam int unsigned {name} = {v};");
            } else {
                let _ = writeln!(o, "  localparam int unsigned {name} = {v};  // {comment}");
            }
        };
        let byte = |v: i64| format!("8'h{v:02X}");
        w!("// {GENERATED_HEADER}");
        w!("// Source: spec/spec.toml (spec_version {}).", self.meta.spec_version);
        w!("// Regenerate: cd sw && cargo run -p splitsys-spec --bin gen");
        w!("// Prose and rationale: docs/SPEC.md, docs/DECISIONS.md.");
        w!("// BUILD_ID is not here: it is a synthesis-time generic of the top level.");
        w!("");
        w!("package splitsys_pkg;");
        w!("");
        w!("  // Documented lint waiver: a shared constants package is never fully used by");
        w!("  // any single module, so Verilator -Wall UNUSEDPARAM is disabled for this file only.");
        w!("  /* verilator lint_off UNUSEDPARAM */");
        w!("");
        w!("  // ---- array (SPEC §3.2)");
        lp(&mut o, "ROWS", a.rows, "");
        lp(&mut o, "COLS", a.cols, "");
        lp(&mut o, "QUAD", a.quad, "quadrant edge");
        lp(&mut o, "N_QUADS", self.n_quads(), "");
        lp(&mut o, "N_PES", a.rows * a.cols, "");
        w!("  localparam bit ENABLE_STRIP = 1'b{};  // default; top-level generic may override", u8::from(a.enable_strip));
        let modes = Self::sorted_by_value(&self.modes);
        w!("  typedef enum logic [7:0] {{");
        for (i, (n, v)) in modes.iter().enumerate() {
            let sep = if i + 1 == modes.len() { "" } else { "," };
            w!("    MODE_{n} = {}{sep}", byte(*v));
        }
        w!("  }} mode_e;");
        lp(&mut o, "FULL_TILE_M", a.rows, "C rows per FULL tile");
        lp(&mut o, "FULL_TILE_N", a.cols, "C cols per FULL tile");
        lp(&mut o, "STRIP_TILE_M", self.strip_tile_m(), "C rows per STRIP tile");
        lp(&mut o, "STRIP_TILE_N", self.strip_tile_n(), "C cols per STRIP tile");
        lp(&mut o, "A_LANES", a.rows, "int8 lanes per ABUF word");
        lp(&mut o, "W_LANES", self.w_lanes(), "int8 lanes per WBUF word");
        w!("  // STRIP: W lanes >= STRIP_W_LANE_FIRST enter at row STRIP_W_ENTRY_ROW, delayed");
        w!("  // STRIP_W_SKEW_BASE + (lane - STRIP_W_LANE_FIRST) cycles. A skew base is 0 in all modes.");
        lp(&mut o, "STRIP_W_LANE_FIRST", a.cols, "");
        lp(&mut o, "STRIP_W_ENTRY_ROW", a.rows / 2, "");
        lp(&mut o, "STRIP_W_SKEW_BASE", a.rows / 2, "");
        let bases = self.w_skew_base_strip();
        let n = bases.len();
        let lanes: Vec<String> = bases.iter().rev().map(|b| format!("8'd{b}")).collect();
        w!("  // Per-lane STRIP W skew base, lane j at [8*j +: 8].");
        w!("  localparam logic [{}:0] W_SKEW_BASE_STRIP = {{{}}};", 8 * n - 1, lanes.join(", "));
        w!("");
        w!("  // ---- latencies in cycles (SPEC §4); *_PROVISIONAL = 1 until the RTL confirms the value");
        for nm in LATENCY_NAMES {
            let l = self.lat(nm);
            let tag = if l.provisional { "PROVISIONAL: " } else { "" };
            lp(&mut o, nm, l.value, &format!("{tag}{}", l.doc));
            w!("  localparam bit {nm}_PROVISIONAL = 1'b{};", u8::from(l.provisional));
        }
        lp(
            &mut o,
            "OPERAND_PORT_OFFSET",
            self.operand_port_offset(),
            "STREAM start s -> word k at array input port in s + OPERAND_PORT_OFFSET + k (= L_RD + 1)",
        );
        w!("");
        w!("  // ---- drain (SPEC §3.5)");
        lp(&mut o, "T_DRAIN_FULL", self.drain.t_drain_full, "");
        lp(&mut o, "T_DRAIN_STRIP", self.drain.t_drain_strip, "");
        lp(&mut o, "T_DRAIN_FULL_INT32", self.drain.t_drain_full_int32, "8 rows x 2 OBUF writes");
        lp(&mut o, "T_DRAIN_STRIP_INT32", self.drain.t_drain_strip_int32, "4 rows x 4 OBUF writes");
        let obw = self.buf("OBUF").word_bytes;
        lp(&mut o, "INT32_WRITES_PER_ROW_FULL", a.cols * 4 / obw, "");
        lp(&mut o, "INT32_WRITES_PER_ROW_STRIP", 2 * a.cols * 4 / obw, "");
        lp(&mut o, "INT32_WORDS_PER_ROW", 2 * a.cols * 4 / obw, "int32 layout: OBUF words per row of a 16-col block");
        w!("");
        w!("  // ---- buffers (SPEC §3.4); byte address = word_index * WORD_BYTES + lane");
        let regions: Vec<(&str, i64)> = BUFFER_NAMES.iter().map(|nm| (*nm, self.buf(nm).region)).collect();
        w!("  typedef enum logic [7:0] {{");
        for (i, (nm, v)) in regions.iter().enumerate() {
            let sep = if i + 1 == regions.len() { "" } else { "," };
            w!("    REGION_{nm} = {}{sep}", byte(*v));
        }
        w!("  }} region_e;");
        lp(&mut o, "N_REGIONS", BUFFER_NAMES.len() as i64, "");
        for nm in BUFFER_NAMES {
            let b = self.buf(nm);
            let pfx = if nm == "RQPARAM" { "RQ" } else { nm };
            if nm == "RQPARAM" {
                lp(&mut o, "RQ_ENTRIES", b.words, "");
            } else {
                lp(&mut o, &format!("{pfx}_WORDS"), b.words, "");
            }
            lp(&mut o, &format!("{pfx}_WORD_BYTES"), b.word_bytes, "");
            lp(&mut o, &format!("{pfx}_WORD_BITS"), b.word_bytes * 8, "");
            lp(&mut o, &format!("{pfx}_BYTES"), b.words * b.word_bytes, "");
            lp(&mut o, &format!("{pfx}_AW"), clog2(b.words), "word address bits");
        }
        w!("");
        w!("  // ---- descriptor (SPEC §3.5), little-endian byte offsets");
        lp(&mut o, "DESC_BYTES", d.bytes, "");
        for f in &d.fields {
            lp(&mut o, &format!("DESC_OFF_{}", f.name.to_uppercase()), f.offset, &format!("{} byte(s)", f.size));
        }
        for f in &d.fields {
            lp(&mut o, &format!("DESC_SIZE_{}", f.name.to_uppercase()), f.size, "bytes");
        }
        w!("  localparam logic [7:0] FLAG_REQUANT_EN = {};", byte(d.flag_requant_en));
        w!("  localparam logic [7:0] FLAG_OUT_INT32 = {};", byte(d.flag_out_int32));
        w!("  localparam logic [7:0] FLAGS_INT8 = {};  // legal flags value: int8 requant", byte(d.flag_requant_en));
        w!("  localparam logic [7:0] FLAGS_INT32 = {};  // legal flags value: int32 bypass", byte(d.flag_out_int32));
        lp(&mut o, "M_MIN", d.m_min, "");
        lp(&mut o, "M_MAX", d.m_max, "");
        lp(&mut o, "K_MIN", d.k_min, "");
        lp(&mut o, "K_MAX", d.k_max, "");
        lp(&mut o, "N_MIN", d.n_min, "");
        lp(&mut o, "N_MAX", d.n_max, "");
        w!("");
        w!("  // ---- requant (SPEC §1.2)");
        lp(&mut o, "RQ_MULT_MIN", self.requant.mult_min, "");
        lp(&mut o, "RQ_MULT_MAX", self.requant.mult_max, "");
        lp(&mut o, "RQ_SHIFT_MIN", self.requant.shift_min, "");
        lp(&mut o, "RQ_SHIFT_MAX", self.requant.shift_max, "");
        w!("");
        w!("  // ---- UART (SPEC §3.8)");
        lp(&mut o, "CLK_HZ", u.clk_hz, "");
        lp(&mut o, "BAUD", u.baud, "");
        lp(&mut o, "OVERSAMPLE", u.oversample, "");
        lp(&mut o, "BAUD_DIV", self.baud_div(), "round(CLK_HZ / (BAUD * OVERSAMPLE))");
        lp(&mut o, "RX_TIMEOUT", u.rx_timeout, "max cycles between byte strobes of one frame (SPEC §3.8)");
        w!("");
        w!("  // ---- protocol (SPEC §3.8)");
        lp(&mut o, "PROTO_VERSION", self.meta.proto_version, "PING version byte");
        w!("  localparam logic [7:0] SYNC_REQ = {};", byte(p.sync_req));
        w!("  localparam logic [7:0] SYNC_RSP = {};", byte(p.sync_rsp));
        lp(&mut o, "MAX_PAYLOAD", p.max_payload, "bytes");
        w!("  localparam logic [7:0] CRC8_POLY = {};", byte(p.crc8_poly));
        w!("  localparam logic [7:0] CRC8_INIT = {};", byte(p.crc8_init));
        w!("  localparam logic [7:0] CRC8_CHECK = {};  // CRC-8 of \"123456789\"", byte(p.crc8_check));
        let magic = p.ping_magic.as_bytes();
        let magic_le = u32::from_le_bytes([magic[0], magic[1], magic[2], magic[3]]);
        w!(
            "  localparam logic [31:0] PING_MAGIC_LE = 32'h{magic_le:08X};  // \"{}\": wire byte i = PING_MAGIC_LE[8*i +: 8]",
            p.ping_magic
        );
        for (tname, prefix, map) in
            [("opcode_e", "OP_", &self.opcodes), ("status_e", "ST_", &self.status), ("poll_e", "POLL_", &self.poll)]
        {
            let items = Self::sorted_by_value(map);
            w!("  typedef enum logic [7:0] {{");
            for (i, (nm, v)) in items.iter().enumerate() {
                let sep = if i + 1 == items.len() { "" } else { "," };
                w!("    {prefix}{nm} = {}{sep}", byte(*v));
            }
            w!("  }} {tname};");
        }
        w!("");
        w!("  // ---- counters (SPEC §3.7), READ_COUNTERS order");
        lp(&mut o, "N_COUNTERS", self.counters.order.len() as i64, "");
        lp(&mut o, "COUNTER_BYTES", self.counters.bytes, "");
        lp(&mut o, "COUNTER_BITS", self.counters.bytes * 8, "");
        for (i, nm) in self.counters.order.iter().enumerate() {
            lp(&mut o, &format!("CTR_{}", nm.to_uppercase()), i as i64, "");
        }
        w!("");
        w!("  // ---- self-test reference values (SPEC §3.9)");
        for (input, v) in self.selftest.checks() {
            w!("  localparam logic [31:0] FLETCHER32_CHECK_{} = 32'h{v:08X};  // \"{input}\"", input.to_uppercase());
        }
        w!("");
        w!("  /* verilator lint_on UNUSEDPARAM */");
        w!("");
        w!("endpackage : splitsys_pkg");
        o
    }
}

fn check_enum(e: &mut Vec<String>, table: &str, m: &BTreeMap<String, i64>, required: &[&str]) {
    for r in required {
        if !m.contains_key(*r) {
            e.push(format!("{table}.{r} is missing"));
        }
    }
    for (k, v) in m {
        if !required.contains(&k.as_str()) {
            e.push(format!("{table}.{k} is not a known name (expected {required:?})"));
        }
        if !(0..=255).contains(v) {
            e.push(format!("{table}.{k} = {v} must fit in u8"));
        }
    }
    let mut vals: Vec<i64> = m.values().copied().collect();
    vals.sort_unstable();
    vals.dedup();
    if vals.len() != m.len() {
        e.push(format!("{table} values are not unique"));
    }
}
